function quizPage(){let a=load('quiz',[]),female=profile.gender==='female';return `<div class="card"><h2>${name(0)}'s friendly interrogation 😏</h2><p>“${female?'Girl, I’m going to ask you the questions your friends are too polite to ask. Don’t anyhow answer, hor.':'Bro, I’m not here to sugarcoat. Fifteen questions. You answer properly, I tell you what I see.'}”</p><p class="muted">15 multiple-choice questions · Not a clinical personality test</p>${questions.map(([q,opts],i)=>`<fieldset class="quiz"><legend>${i+1}. ${questionAlternates[i][(Math.floor(Date.now()/86400000)+i+(female?1:0))%3]}</legend>${opts.map((o,j)=>`<label class="choice"><input type="radio" name="q${i}" value="${j}" ${a[i]===j?'checked':''}><span>${o}</span></label>`).join('')}</fieldset>`).join('')}<button onclick="submitQuiz()">Okay ${name(0)}, judge me →</button><p class="small muted">Questions rotate daily while keeping the same 15 relationship themes.</p><p id="status"></p></div>`}
function submitQuiz(){let a=questions.map((_,i)=>document.querySelector('input[name="q'+i+'"]:checked')?.value??'');if(a.some(x=>x==='')){$('#status').textContent='Oi, all 15 questions first. No escaping the difficult ones!';return}store('quiz',a.map(Number));go('quizresult')}function quizResult(){let a=load('quiz',[]),traits=[['trust and steady commitment','shared experiences and laughter','growth and ambition','emotional closeness'],['a calm, cosy connection','an adventurous partnership','an active social life','a flexible balance']];let p=traits[0][a[0]||0],v=traits[1][a[1]||0],need=['consistency and patience','space to process feelings','gentle reassurance','practical teamwork'][a[2]||0];return `<h1>${name(0)}'s take on you 💗</h1><div class="card"><p>“${profile.gender==='female'?'Girl, listen.':'Bro, listen up.'} From your answers, you seem to value <strong>${p}</strong>, while enjoying <strong>${v}</strong>. Not bad ah — knowing these things early helps you choose wisely.”</p><h2>The partner you may be</h2><p>You could be a thoughtful partner who values ${esc(questions[3][1][a[3]||0].toLowerCase())} and wants to build something meaningful. Your preferences are clues, not a scientific personality diagnosis.</p><h2>What you may need in a partner</h2><p>Someone who offers ${need}, respects your boundaries, and can talk openly about differences. Look for compatible values, not just sparks.</p><h2>How your other friends will use this</h2><p>${esc(name(1))} will use your preferred date pace, social energy, spending style and ways of showing care to rank activities and suggest outfit details. These are preferences, not personality labels.</p><button class="secondary" onclick="go('friend1')">Let ${name(1)} plan with these insights →</button><h2>One thing to work on</h2><p>Be clear about your expectations without expecting anyone to read your mind. Good communication is attractive, lah.</p><nav><button onclick="saveQuizResult()">Save result</button><button class="secondary" onclick="copyQuizResult()">Copy</button><button class="secondary" onclick="shareQuizResult()">Share</button><button class="secondary" onclick="go('friend0')">Retake quiz</button></nav><p id="quizFeedback" role="status"></p></div>`}function quizResultText(){const el=document.createElement('div');el.innerHTML=quizResult();return (el.innerText||el.textContent||'').replace(/Save result.*$/s,'').trim()}function saveQuizResult(){const t=quizResultText();store('quizSaved',{text:t,date:new Date().toISOString(),answers:load('quiz',[])});const el=$('#quizFeedback');if(el)el.textContent='Saved on this device! 💗'}async function copyQuizResult(){const t=quizResultText();try{await navigator.clipboard.writeText(t);$('#quizFeedback').textContent='Copied!'}catch{prompt('Copy your result:',t)}}async function shareQuizResult(){const t=quizResultText();if(navigator.share){try{await navigator.share({title:'My AI Steady Mai SG relationship insights',text:t})}catch(e){if(e.name!=='AbortError')copyQuizResult()}}else copyQuizResult()}
function relationshipSignals(){const a=load('quiz',[]);if(a.length!==15)return null;const styles=['calm and cosy','adventurous and curious','social and energetic','balanced and flexible'];const labels=['quality time','acts of service','words of affirmation','thoughtful gifts'];const social=['quiet spaces','small groups','lively crowds','flexible company'];return {style:styles[a[1]||0],styleIndex:a[1]||0,love:labels[a[3]||0],social:social[a[6]||0],socialIndex:a[6]||0,spend:a[7]||0,communication:['talk it out promptly','take some space first','offer reassurance','solve things together'][a[2]||0],intent:['marriage and family','long-term partnership','exploring','undecided'][a[11]||0]}}function ageBand(){let n=Number(profile.age)||25;return n<30?'20s':n<40?'30s':n<50?'40s':n<60?'50s':'60+'}function ageDateContext(){const band=ageBand();return ({'20s':'Try discovery dates, playful activities and affordable new experiences.','30s':'Consider experiences that balance novelty with meaningful time together.','40s':'Consider quality conversation, culture and distinctive experiences without unnecessary rushing.','50s':'Consider comfortable pacing, cultural experiences and interesting food or performances.','60+':'Consider accessibility, seating, manageable walking and unhurried experiences.'})[band]}function quizBridge(){let q=relationshipSignals();return q?`<div class="insight"><strong>💗 ${name(0)}’s insights are in use</strong><p class="small">You lean toward ${esc(q.style)} experiences, appreciate ${esc(q.love)}, and prefer ${esc(q.social)}. ${name(1)} will use these as gentle hints, not rigid rules.</p><button class="secondary" onclick="go('quizresult')">Review my personality insights</button></div>`:`<div class="insight"><strong>Make your recommendations more personal</strong><p class="small">Complete ${name(0)}’s 15-question relationship quiz so ${name(1)} can tailor date ideas and outfit advice.</p><button class="secondary" onclick="go('friend0')">Take the quiz</button></div>`}
const dateSlots=[['morning','Morning · 9am–12pm'],['afternoon','Afternoon · 12pm–5pm'],['evening','Evening · 5pm–10pm'],['amhalf','AM half-day · 9am–1pm'],['pmhalf','PM half-day · 1pm–7pm'],['fullday','Full day · 9am–9pm']];
function dateInputs(prefix){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());const date=d.toISOString().slice(0,10);return `<label for="${prefix}Date">Date</label><input id="${prefix}Date" type="date" min="${date}" value="${date}"><label for="${prefix}Slot">Time of day</label><select id="${prefix}Slot">${dateSlots.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select>`}
function slotHours(slot){return ({morning:[9,12],afternoon:[12,17],evening:[17,22],amhalf:[9,13],pmhalf:[13,19],fullday:[9,21]})[slot]||[12,17]}
function slotLabel(slot){return dateSlots.find(x=>x[0]===slot)?.[1]||slot}
function datePage(){return `<div class="card"><h2>What to wear 👕</h2><p>“Tell me your vibe and plans. I’ll help you look good without trying too hard.”</p><p class="small muted">${esc(ageDateContext())}</p><label>Your style</label><select id="style"><option>Casual & comfy</option><option>Trendy streetwear</option><option>Smart casual</option><option>Chic & polished</option></select><label>Indoor or outdoor?</label><select id="setting"><option>Mixed</option><option>Mostly indoor</option><option>Mostly outdoor</option></select>${dateInputs("outfit")}<label>Where? (Singapore location)</label><input id="outfitLoc" placeholder="e.g. Orchard"><button onclick="outfit()">Suggest my outfit</button><div id="outfitResult"></div></div><div class="card"><h2>Plan our date 🗺️</h2><p>“Give me the details, bestie. I’ll factor in your age, preferences, weather and real events.”</p><label>Your location <span class="muted small">(optional)</span></label><input id="loc1" placeholder="e.g. Hougang — leave blank for islandwide ideas"><label>Your date's location <span class="muted small">(optional)</span></label><input id="loc2" placeholder="e.g. Jurong East — leave blank if unsure"><p class="small muted">No locations? No problem! I’ll suggest suitable spots across Singapore. Add one or both to help narrow the area.</p>${dateInputs("plan")}<label>Preferred activity</label><select id="activity">${['Surprise me','Cafe & conversation','Dinner','Nature walk','Museum & arts','Movie','Games & activities','Shopping & dessert','Waterfront stroll','Stay in & cook'].map(x=>`<option>${x}</option>`).join('')}</select><label>Budget per person</label><select id="budget"><option value="1">$ — under S$30</option><option value="2">$$ — S$30–80</option><option value="3">$$$ — S$80+</option></select><button onclick="plan()">Build date ideas →</button><p class="small muted">Prefer a cosy night? Choose Stay in & cook. Surprise me also considers your homebody quiz answers.</p><p id="status"></p></div>`}async function outfit(){let s=$('#style').value,setting=$('#setting').value,when=$('#outfitDate').value+'T'+String(slotHours($('#outfitSlot').value)[0]).padStart(2,'0')+':00',loc=$('#outfitLoc').value||'Singapore',result=$('#outfitResult');result.innerHTML='<p>Checking the forecast…</p>';let weather='Singapore is typically warm and humid. Pack a compact umbrella and a light layer for air-conditioned venues.';try{let r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=1.3521&longitude=103.8198&hourly=temperature_2m,precipitation_probability&timezone=Asia%2FSingapore&forecast_days=3');if(!r.ok)throw Error();let j=await r.json(),idx=j.hourly.time.findIndex(t=>t.slice(0,13)===(when||new Date().toISOString()).slice(0,13));if(idx<0)idx=0;let max=Math.max(...j.hourly.precipitation_probability.slice(idx,idx+12)),temp=j.hourly.temperature_2m[idx];weather=`Singapore forecast near your chosen time: around ${temp}°C, with up to ${max}% hourly rain probability in the following 12 hours. This is a Singapore-wide forecast, not a street-level prediction.`}catch{}let female=profile.gender==='female',q=relationshipSignals();let tops=female?{'Casual & comfy':'airy cotton blouse or relaxed tee','Trendy streetwear':'statement top with a light overshirt','Smart casual':'breathable blouse or refined knit top','Chic & polished':'structured lightweight blouse or elegant midi dress'}:{'Casual & comfy':'breathable cotton tee or polo','Trendy streetwear':'relaxed overshirt over a plain tee','Smart casual':'linen or Oxford button-down shirt','Chic & polished':'lightweight collared shirt or unstructured blazer'};let bottom=female?(s==='Chic & polished'?'midi skirt or tailored trousers':'comfortable wide-leg trousers, skirt or jeans'):(s==='Casual & comfy'?'clean chinos or straight-cut jeans':'well-fitting chinos or tailored trousers');let extras=q?(q.styleIndex===1?' Add a practical crossbody or small bag for exploring.':q.styleIndex===0?' Keep the outfit understated and comfortable for a long chat.':q.styleIndex===2?' A tasteful accent colour can make it feel more expressive.':' Choose versatile pieces you can dress up or down.'):' Take the relationship quiz for a more personalised finishing touch.';let text=`For your ${ageBand()} and ${s.toLowerCase()} preference: Try ${tops[s]}, ${bottom}, and supportive, clean shoes. ${setting==='Mostly outdoor'?'Prioritise breathable fabrics, sun protection and walking comfort.':'Bring a light layer for strong air-conditioning.'}${extras} ${weather}`;let outfitAlternatives=female?['Swap trousers for a breezy midi skirt and choose lightweight flats.','Try a breathable coordinated set with comfortable sneakers and a small crossbody bag.','For a dressier mood, choose a simple midi dress with low heels or flats.']:['Try a relaxed linen shirt, straight-cut trousers and clean sneakers.','Swap to a textured polo, lightweight chinos and comfortable loafers.','For a smarter look, pair an unstructured overshirt with a plain tee and tailored trousers.'];let rotate=(new Date(when).getDate()+s.length+setting.length)%outfitAlternatives.length;let alternative=outfitAlternatives[rotate];if(q?.styleIndex===0)alternative+= ' Keep fabrics soft and fuss-free for a longer conversation.';if(setting==='Mostly outdoor')alternative+=' Avoid heavy layers in the humidity.';result.innerHTML=`<div class="card"><p>${esc(text)}</p><p><strong>Another outfit option:</strong> ${esc(alternative)}</p><p class="small muted">${esc(name(0))}'s quiz insights and your chosen style help personalise these combinations. Choose what feels comfortable and authentic to you.</p><a target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${encodeURIComponent((female?'women womenswear female':'men menswear male')+' '+s+' Singapore date outfit inspiration')}">Browse outfit inspiration on Google Images ↗</a></div>`}function plan(){let o={a:$('#loc1').value.trim(),b:$('#loc2').value.trim(),time:$('#planDate').value+'T'+String(slotHours($('#planSlot').value)[0]).padStart(2,'0')+':00',slot:$('#planSlot').value,activity:$('#activity').value,budget:Number($('#budget').value)};if(!$('#planDate').value){$('#status').textContent='Choose your date first, bestie. Locations are optional!';return}if(new Date($('#planDate').value+'T23:59:59')<new Date()){$('#status').textContent='Choose a future date and time.';return}store('plan',o);go('itineraries');refreshSmartIdeas()}// Activity-specific, curated Singapore venues. Prices are planning allowances, not live quotes.
