function homebodyStrength(){const a=load('quiz',[]);if(a.length!==15)return 0;return (a[1]===0?3:0)+(a[6]===0?4:a[6]===1?2:0)+(a[3]===0?1:0)}
function compactFriendContext(){const q=relationshipSignals();if(!q)return `<div class="context-strip"><span>✨ Want more personal ideas? <button class="context-link" onclick="go('friend0')">Take ${esc(name(0))}'s quiz →</button></span></div>`;return `<div class="context-strip"><span>✨ Personalised for your <strong>${esc(q.style)}</strong> vibe${homebodyStrength()>=4?', including cosy nights in':''}.</span><button class="context-link" onclick="go('quizresult')">View insights ↗</button></div>`}

function recipeRank(r,v,weather){
 const text=(r.title+' '+r.category+' '+r.ingredients.join(' ')).toLowerCase();
 const soup=/soup|broth|stew|porridge|congee|laksa|mee sua|bak kut teh|ramen/.test(text);
 const pasta=/pasta|spaghetti|carbonara|aglio|macaroni|lasagne|linguine|fettuccine/.test(text);
 const cool=/salad|soba|cold|chilled|sandwich|sushi|poke|fruit/.test(text);
 const snack=/toast|snack|cake|cookie|pancake|dessert|sandwich|tart|waffle/.test(text);
 let score=0;
 if(v.kind==='soup')score+=soup?15:-3;
 if(v.kind==='pasta')score+=pasta?18:-3;
 if(v.kind==='cool')score+=cool?15:-3;
 if(v.kind==='snack')score+=snack?15:-3;
 if(weather==='rain')score+=soup?12:0;
 if(weather==='hot')score+=cool?12:0;
 if(v.kind==='dinner')score+=/rice|noodle|pasta|chicken|fish|tofu|beef|pork|vegetable/.test(text)?7:0;
 const mins=Number(r.minutes)||60;
 if(mins<=35)score+=6;else if(mins<=60)score+=4;else if(mins>110)score-=5;
 const signals=relationshipSignals?.();
 if(signals&&/adventur|explor|novel|spontan/i.test(JSON.stringify(signals)))score+=/japanese|korean|thai|indian|western|italian/.test(r.cuisine.toLowerCase())?3:0;
 return score;
}
function howCookRecipeUrl(id){
 let url=load('howCookUrl','https://howcooksgv8x.matkwong97.workers.dev/').trim();
 try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))return '';u.searchParams.set('recipe',String(id));return u.href}catch{return ''}
}
function recipeCardHtml(r,v,weather){
 const href=howCookRecipeUrl(r.id);
 return `<div class="hc-recipe-card"><p><strong>🍳 Cook together: ${esc(r.title)}</strong></p><p class="small muted">About ${Number(r.minutes)} min · From How Cook SG</p><details><summary>Ingredients & recipe info</summary><p class="small">${esc(r.ingredients.slice(0,8).join(', '))}</p>${href?`<a href="${esc(href)}" target="_blank" rel="noopener">Find recipe on How Cook SG ↗</a><p class="small muted">Opens How Cook SG. The original site may not automatically select this recipe; search for its title if needed.</p>`:''}</details></div>`;
}
let steadyScreenCache={};
function screenRecent(kind){return load('screenRecent_'+kind,[])}
async function screenRecommendations(kind,elementId){
 const el=document.getElementById(elementId);if(!el)return;
 try{
  let data=steadyScreenCache[kind];if(!data){const r=await fetch('/api/screen?kind='+kind,{signal:AbortSignal.timeout(10000)});data=await r.json();if(data.status==='live')steadyScreenCache[kind]=data}
  if(!document.getElementById(elementId))return;
  if(data.status!=='live'||!data.items?.length){el.innerHTML='<p class="small muted">Film suggestions unavailable right now.</p>';return}
  const recent=screenRecent(kind),items=data.items.filter(x=>x.votes>=40&&x.rating>=6.3);
  const pool=(items.length?items:data.items).filter(x=>!recent.includes(String(x.id)));
  const eligible=pool.length?pool:(items.length?items:data.items);
  const pick=eligible[Math.floor(Math.random()*eligible.length)];
  if(!pick)return;
  store('screenRecent_'+kind,[String(pick.id),...recent].slice(0,Math.min(12,Math.max(2,data.items.length-2))));
  el.innerHTML=`<p class="small"><strong>🎬 ${esc(pick.title)}</strong> · TMDB ${pick.rating??'N/A'}/10</p><p class="small muted">${kind==='netflix'?'Streaming availability':'Cinema showtimes'} not guaranteed. <a href="${esc(pick.link)}" target="_blank" rel="noopener">Film details ↗</a></p><button class="secondary" onclick="screenRecommendations('${kind}','${elementId}')">Try another title ↻</button>`;
 }catch{if(document.getElementById(elementId))el.textContent='Film suggestions temporarily unavailable.'}
}
async function nearbyDining(area,budget,elementId){
 const el=document.getElementById(elementId);if(!el)return;
 try{let r=await fetch('/api/restaurants?area='+encodeURIComponent(area),{signal:AbortSignal.timeout(10000)});let j=await r.json();if(!document.getElementById(elementId))return;
 if(j.status!=='live'||!j.items?.length)throw Error('Unavailable');
 const cafes=j.items.filter(x=>x.kind==='cafe'),restaurants=j.items.filter(x=>x.kind==='restaurant');
 const picks=(budget===1?[...cafes,...restaurants]:[...restaurants,...cafes]).slice(0,4);
 el.innerHTML='<h3>☕ Nearby dining ideas in '+esc(area)+'</h3>'+picks.map(x=>`<p><strong>${esc(x.name)}</strong> · ${x.kind==='cafe'?'Café':'Restaurant'}${x.cuisine?' · '+esc(x.cuisine):''} <a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(x.name+' '+area+' Singapore')}">Map & menu ↗</a></p>`).join('')+'<p class="small muted">These are real mapped venues from OpenStreetMap, not price-verified matches. Your budget is a planning preference; check menus and opening hours before going.</p>';
 }catch{if(document.getElementById(elementId))el.innerHTML='<p class="small muted">Live restaurant lookup unavailable. <a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('cafes restaurants '+area+' Singapore')+'">Browse restaurants on Maps ↗</a></p>'}
}
function homeDateDetail(v,weather){
 const id='how-cook-match-'+Math.random().toString(36).slice(2);
 queueMicrotask(()=>loadHowCookCatalogue().then(all=>{
   const el=document.getElementById(id);if(!el)return;
   const ranked=[...all].sort((a,b)=>recipeRank(b,v,weather)-recipeRank(a,v,weather));
   const shortlist=ranked.slice(0,Math.min(12,ranked.length));
   const prev=load('recipeRecent',[]),fresh=shortlist.filter(r=>!prev.includes(String(r.id))),options=fresh.length?fresh:shortlist;const chosen=options[Math.floor(Math.random()*Math.min(7,options.length))];if(chosen)store('recipeRecent',[String(chosen.id),...prev].slice(0,8));
   el.innerHTML=chosen?recipeCardHtml(chosen,v,weather):'<p class="small">No verified recipes found.</p>';
 }).catch(()=>{const el=document.getElementById(id);if(el)el.textContent='How Cook SG catalogue could not be loaded. Please retry when online.'}));
 return `<div id="${id}" class="hc-recipe-card" aria-live="polite"><p class="small muted">Matching this date with a verified How Cook SG recipe…</p></div>`;
}
function howCookSettings(){return `<div class="card"><h3>🍳 Connect How Cook SG</h3><p class="small muted">Paste the real URL of your How Cook SG site. It stays on this device. Recipes are matched against the verified 110-recipe How Cook SG v35 catalogue included in this app. Add your How Cook SG site URL to open exact recipes; the companion How Cook SG update enables direct links.</p><label for="howCookUrl">How Cook SG website URL</label><input id="howCookUrl" type="url" placeholder="https://your-how-cook-site.example" value="${esc(load('howCookUrl',''))}"><button class="secondary" onclick="saveHowCookUrl()">Save recipe link</button><p id="howCookStatus" role="status"></p></div>`}
function saveHowCookUrl(){let value=document.getElementById('howCookUrl').value.trim();if(value){try{let u=new URL(value);if(!['https:','http:'].includes(u.protocol))throw Error()}catch{document.getElementById('howCookStatus').textContent='Enter a valid http:// or https:// URL.';return}}store('howCookUrl',value);document.getElementById('howCookStatus').textContent='Saved on this device.'}
