function zone(loc){let key=Object.keys(zoneMap).find(k=>loc.toLowerCase().includes(k.toLowerCase()));return key?zoneMap[key]:null}
dateCatalogue['Stay in & cook']=homeDates;
function matchScore(v,o,i){let z1=zone(o.a),z2=zone(o.b),vz=areaZone[v.area]||'central',score=0;if(z1===vz)score+=2;if(z2===vz)score+=2;if(z1&&z2&&z1===z2&&vz===z1)score+=2;if(!z1||!z2)score+=1;if(o.budget===1&&v.cost>25)score-=3;if(o.budget===2&&v.cost>70)score-=3;let evening=['evening','pmhalf'].includes(o.slot);if(evening&&v.day&&!v.night)score-=8;if(!evening&&v.night&&!v.day)score-=2;if(o.slot==='fullday'&&v.day)score+=1;return score-i*.01}
function buildIdeas(o){let catalog=o.activity==='Surprise me'?Object.entries(dateCatalogue).flatMap(([activity,vs])=>vs.slice(0,2).map(v=>({...v,category:activity}))):dateCatalogue[o.activity].map(v=>({...v,category:o.activity}));let picks=catalog.map((v,i)=>({...v,score:matchScore(v,o,i)})).sort((a,b)=>b.score-a.score);let chosen=[];for(let v of picks){if(chosen.length>=4)break;if(o.activity==='Surprise me'&&chosen.some(x=>x.category===v.category))continue;chosen.push(v)}return chosen.map(v=>{let late=['evening','pmhalf'].includes(o.slot);let short=['morning','afternoon','evening'].includes(o.slot);let steps=[`Meet at ${v.meet}. ${o.a||o.b?`Check routes${o.a?` from ${o.a}`:``}${o.a&&o.b?` and`:``}${o.b?` from ${o.b}`:``}; travel times are not calculated here.`:`This is an islandwide suggestion; check your journey before heading out.`}`,...(late?[`Start with ${v.food.toLowerCase()}.`]:[]),v.activity+'.',...(!short?[v.extra+'.']:[]),...(!late?[`Finish with ${v.food.toLowerCase()}.`]:[v.extra+'.'])];return {...v,steps,price:`Approx. S$${v.cost} per person before transport; actual prices vary`,note:v.day&&late?'This venue may close before or during your selected time. Check opening hours and consider an earlier slot.':v.outdoor?'Outdoor plan: check weather and have an indoor backup.':'Check opening hours, tickets and booking requirements before travelling.'}})}
function itineraryResults(){let o=load('plan',{});if(!o.time)return '<p>No plan yet.</p>';let picks=buildIdeas(o);window.steadyDateIdeas=picks;let d=new Date(o.time).toLocaleDateString('en-SG',{dateStyle:'medium'})+' · '+slotLabel(o.slot||'afternoon');return `<h1>${name(1)}'s date ideas 💕</h1><p>“I’m combining your preferences with suitable places, the forecast and date-specific event listings. You choose what feels right!”</p><p class="muted">${esc([o.a,o.b].filter(Boolean).join(" + ")||"Islandwide Singapore suggestions")} · ${esc(d)} · ${esc(o.activity)}</p><p class="small muted">${esc(ageDateContext())} ${relationshipSignals()?`Your quiz suggests ${esc(relationshipSignals().style)} experiences.`:"Take the quiz for more personalised ideas."}</p><div class="card"><h3>Fresh picks, based on your date</h3><p id="smartStatus" class="small muted">Checking Singapore weather and date-specific happenings…</p><button onclick="refreshSmartIdeas(true)">🎲 Surprise me again — fresh mix</button></div>${[].map((v,i)=>`<div class="card"><h2>${i+1}. ${esc(v.title)}</h2><p><strong>${esc(v.category)}</strong> · ${esc(v.price)}</p><p class="small muted">Main destination: ${esc(v.venue)}</p><details><summary>See full itinerary</summary>${v.steps.map((step,j)=>`<p>${j+1}. ${esc(step)}</p>`).join('')}<p class="small muted">${esc(v.note)}</p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(v.address)}" target="_blank" rel="noopener">Open main venue in Google Maps ↗</a></details><nav><button class="secondary" onclick="likeItin(${i})">${profile.gender==='female'?'♡ Heart':'👍 Like'}</button><button onclick="saveItin(${i})">Save</button><button class="secondary" onclick="copyItin(${i})">Copy</button><button class="secondary" onclick="shareItin(${i})">Share</button></nav></div>`).join('')}<div class="card"><h3>Saved ideas</h3><div id="saved">${load('saved',[]).map(v=>`<p>♥ ${esc(v.title)}</p>`).join('')||'None yet.'}</div></div><p>“Aiyo, hope you both have a lovely time! Just be present and enjoy the company.”</p>`}
function planText(i){let o=load('plan',{}),v=(window.steadyDateIdeas||buildIdeas(o))[i];return `Date idea: ${v.title}\nActivity: ${v.category}\nWhen: ${o.time.slice(0,10)} · ${slotLabel(o.slot||'afternoon')}\nMeeting point: ${v.meet}\n${v.steps.map((s,j)=>`${j+1}. ${s}`).join('\n')}\n${v.note}\nCheck transport, opening hours and costs before going.`}
function copyItin(i){let t=planText(i);if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t).then(()=>alert('Copied!')).catch(()=>prompt('Copy this:',t));else prompt('Copy this:',t)}
