function saveItin(i){let o=load('plan',{}),v=(window.steadyDateIdeas||buildIdeas(o))[i],a=load('saved',[]),item={title:v.title,text:planText(i)};if(!a.some(x=>x.text===item.text))a.push(item);store('saved',a);$('#saved').innerHTML=a.map(x=>`<p>♥ ${esc(x.title)}</p>`).join('')}
