function toggleWeddingTask(i,v){let t=load('weddingTasks',{});t[i]=v;store('weddingTasks',t);render()}function saveWeddingNotes(){store('weddingSeatNotes',$('#seatNotes').value)}function copyWeddingSummary(){let d=load('wedding',{}),left=weddingDays(d.date),t=load('weddingTasks',{});let content=`Wedding plan: ${d.date||'Date TBD'} (${left??'unknown'} days remaining)\nVenue: ${d.venue}\nBudget: ${weddingMoney(d.amount)}\nGuests: ${d.guests}, tables: ${Math.ceil(d.guests/d.seats)}\nNotes: ${load('weddingSeatNotes','')}\n\nChecklist:\n${weddingTasks.map((x,i)=>(t[i]?'[x] ':'[ ] ')+x[1]).join('\n')}`;navigator.clipboard?.writeText(content).then(()=>alert('Wedding plan copied!')).catch(()=>prompt('Copy your plan:',content))||prompt('Copy your plan:',content)}
function marriageAdvice(){let t=$('#challenge').value.trim();if(t.length<12){$('#advice').textContent='Tell me a little more about what happened, can?';return}let s=t.toLowerCase(),a=/violence|hit me|abuse|threat|unsafe|scared|forced/.test(s)?'Your safety matters more than fixing the argument. If you are in immediate danger in Singapore, call 999. Consider reaching out to a trusted person or a family violence support service.':/money|finance|spend|debt|saving|budget/.test(s)?'Money tension is common. Pick a calm time to compare your priorities, agree on shared expenses and set a spending threshold that requires discussion.':/chores|housework|clean|laundry|cook/.test(s)?'Uneven housework can build resentment. Write down recurring tasks together, divide ownership clearly and review the arrangement after two weeks.':/in-law|parents|family|mother|father/.test(s)?'Family boundaries can be delicate. Discuss what each of you needs privately first, then agree on a respectful message you can present as a team.':/intimacy|sex|affection|romance/.test(s)?'Different needs for closeness deserve a gentle conversation without pressure. Ask what helps each of you feel connected, and respect consent and boundaries.':/argu|fight|communicat|listen|ignored/.test(s)?'Try starting with “I feel…” rather than blame. Reflect back what your spouse says before responding, and agree to pause if the discussion gets heated.':'It sounds like something important is weighing on you. Try naming the specific moment that hurt, what you needed instead, and one small change you could request kindly.';$('#advice').innerHTML=`<div class="card"><p>“I hear you. ${esc(a)}”</p><p>“One small step today: ask, ‘Can we set aside 20 minutes to understand each other, without trying to win?’ You deserve to be heard, and so does your spouse.”</p><p class="small muted">This is general support, not professional counselling.</p></div>`}render();

