async function fetchLiveEvents(o){const date=o.time.slice(0,10);try{const q=new URLSearchParams({date});const r=await fetch('/api/events?'+q,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('Events API unavailable');const data=await r.json();return {...data,events:Array.isArray(data.events)?data.events:[]}}catch{return {events:[],status:'error',message:'Live events could not be retrieved; showing permanent attractions.'}}}

function likeItin(i){let v=(window.steadyDateIdeas||[])[i];if(!v)return;let likes=load('dateLikes',{});likes[v.category]=(likes[v.category]||0)+1;likes[v.area]=(likes[v.area]||0)+0.35;store('dateLikes',likes);alert((profile.gender==='female'?'Hearted!':'Liked!')+' I’ll look for more '+v.category.toLowerCase()+' ideas next time.');}
async function smartWeather(o){let day=o.time.slice(0,10),now=new Date(),days=Math.ceil((new Date(day+'T12:00:00+08:00')-now)/86400000);if(days<0||days>15)return {state:'unknown',message:'Weather forecast not available for that date yet.'};try{let q=new URL('https://api.open-meteo.com/v1/forecast');q.search=new URLSearchParams({latitude:'1.3521',longitude:'103.8198',hourly:'precipitation_probability,precipitation',timezone:'Asia/Singapore',forecast_days:String(Math.min(16,Math.max(1,days+2)))});let r=await fetch(q,{signal:AbortSignal.timeout(6500)});if(!r.ok)throw Error();let j=await r.json(),[start,end]=slotHours(o.slot);let idx=j.hourly.time.map((t,i)=>t.slice(0,10)===day&&Number(t.slice(11,13))>=start&&Number(t.slice(11,13))<end?i:-1).filter(i=>i>=0);if(!idx.length)throw Error();let peak=Math.max(...idx.map(i=>j.hourly.precipitation_probability[i]||0));return {state:peak>=55?'rain':'clear',message:`Singapore-wide forecast: up to ${peak}% hourly chance of rain during your chosen period. ${peak>=55?'Indoor plans prioritised.':'Outdoor options are possible; bring an umbrella.'}`}}catch{return {state:'unknown',message:'Live weather unavailable. Outdoor plans include a rain backup.'}}}
function weightedShuffle(arr,fn){return arr.map(v=>({v,k:-Math.log(Math.max(Math.random(),.000001))/Math.max(.1,fn(v))})).sort((a,b)=>a.k-b.k).map(x=>x.v)}
async function refreshSmartIdeas(again=false){let target=document.querySelector('#smartStatus');if(!target)return;let run=++smartRun,o=load('plan',{});if(!o.time)return;target.textContent='Finding a new mix of date ideas…';let [weather,live]=await Promise.all([smartWeather(o),fetchLiveEvents(o)]);if(run!==smartRun||!document.querySelector('#smartStatus'))return;let date=o.time.slice(0,10),likes=load('dateLikes',{}),recent=load('dateRecent',[]),surprise=o.activity==='Surprise me';let candidates=Object.entries(dateCatalogue).flatMap(([cat,items])=>items.map(v=>({...v,category:cat,id:'place:'+v.title})));for(let e of (live.status==='live'?live.events:[])){if(date!==e.date)continue;if(!surprise&&o.activity!==e.category&&e.category!=='Surprise me')continue;let v={...e,meet:e.venue,address:e.address||e.venue,area:e.area||'central',cost:0,category:e.category==='Surprise me'?'Games & activities':e.category,id:e.id,extra:'Take photos and talk about your favourite moments',food:'A nearby café or meal',activity:'Attend '+e.title,event:true,live:true,indoor:e.indoor===true,outdoor:e.indoor===false};candidates.push(v)}if(!surprise)candidates=candidates.filter(v=>v.category===o.activity);let [start,end]=slotHours(o.slot);candidates=candidates.filter(v=>!(v.day&&start>=17&&!v.night)).filter(v=>o.budget===1?v.cost<=30:o.budget===2?v.cost<=80:true);if(weather.state==='rain')candidates=candidates.filter(v=>v.indoor||!v.outdoor);if(!candidates.length){target.textContent='No suitable matches for this slot. Try another activity or time.';return}let pool=weightedShuffle(candidates,v=>{let q=relationshipSignals(),band=ageBand();let weight=2+(likes[v.category]||0)*.8+(likes[v.area]||0)*.4+(v.live?5:0);if(v.home)weight+=homebodyStrength()*1.9;if(weather.state==='rain'&&v.home)weight+=3;if(q){if(q.styleIndex===0&&['Cafe & conversation','Museum & arts','Nature walk'].includes(v.category))weight+=2;if(q.styleIndex===1&&['Games & activities','Museum & arts','Nature walk'].includes(v.category))weight+=2;if(q.styleIndex===2&&['Games & activities','Shopping & dessert','Dinner'].includes(v.category))weight+=1.8;if(q.spend===0&&v.cost<=20)weight+=1.5;}if(band==='20s'&&['Games & activities','Shopping & dessert'].includes(v.category))weight+=.9;if(band==='30s'&&['Dinner','Museum & arts'].includes(v.category))weight+=.9;if(['40s','50s','60+'].includes(band)&&['Museum & arts','Cafe & conversation','Dinner'].includes(v.category))weight+=1.3;if(band==='60+'&&v.outdoor)weight*=.8;if(recent.includes(v.id))weight*=.08;if(o.a&&zone(o.a)===(areaZone[v.area]||'central'))weight+=2;if(o.b&&zone(o.b)===(areaZone[v.area]||'central'))weight+=2;return weight});let chosen=[];for(let v of pool){if(chosen.length===4)break;if(surprise&&chosen.some(x=>x.category===v.category))continue;chosen.push(v)}if(chosen.length<4)for(let v of pool){if(chosen.length>=4)break;if(!chosen.includes(v))chosen.push(v)}let output=chosen.map(v=>{
  const companions=Object.entries(dateCatalogue).flatMap(([cat,items])=>items.map(x=>({...x,category:cat})))
    .filter(x=>!x.event && x.title!==v.title && !v.home && !x.home && x.area===v.area && x.cost+v.cost<=(o.budget===1?30:o.budget===2?80:999))
    .filter(x=>weather.state!=='rain'||x.indoor||!x.outdoor)
    .filter(x=>!(x.day&&start>=17&&!x.night));
  const side=companions.sort((a,b)=>(a.category===v.category?-1:0)-(b.category===v.category?-1:0))[0];
  const isEvent=!!v.event;
  let steps=v.home?[`Choose a recipe and shop for ingredients together.`,`Split the preparation and cook the meal as a team.`,`Set the table and enjoy your homemade food.`,`Choose a film or series on a service you already use.`,`Wash up together and enjoy a relaxed evening.`]:[`Meet at ${v.meet}. Confirm your travel route and event/venue opening hours.`,
    isEvent?`Main highlight: ${v.activity}${v.time?' at '+v.time:''}. Check the organiser's listing for the selected date, session and tickets before going.`:`Main highlight: ${v.activity}.`,
    ...(side?[`Afterwards, ${side.activity.toLowerCase()} at ${side.venue||side.title} (${side.area}). Confirm its opening hours and allow time to travel.`]:[v.extra+'.']),
    `Round off with ${v.food.toLowerCase()}.`];
  let total=v.cost+(side?side.cost:0);
  return {...v,steps,companion:side,price:`${v.live?'Event admission price unknown; ':'Approx. S$'+total+' per person for highlighted activities; '}food/transport may cost extra`,
    note:v.home?'Ingredient costs are approximate; streaming requires a subscription.':isEvent?'Live event listing from '+v.source+'. Exact ticket prices, availability, operating hours and indoor status are not verified; check the organiser before travelling.':weather.state==='unknown'?'Check the weather before travelling.':'Confirm opening hours, bookings and weather before setting off.'}
});window.steadyDateIdeas=output;store('dateRecent',[...output.map(v=>v.id),...recent].slice(0,16));target.textContent=weather.state==='rain'?'Rain-friendly ideas selected.':weather.state==='clear'?'Ideas matched to your date and preferences.':'Here are some ideas for your date.';let cards=target.closest('.card');let container=cards.parentElement;for(let el of [...container.querySelectorAll('.smart-idea')])el.remove();let anchor=cards;for(let [i,v] of output.entries()){let el=document.createElement('div');el.className='card smart-idea';el.innerHTML=`<h2>${i+1}. ${esc(v.title)} ${v.event?'✨':''}</h2><p><strong>${esc(v.category)}</strong> · ${esc(v.price)}</p><p class="small muted">${v.event?'Live event · ':''}${esc(v.venue)}</p>${v.companion?`<p class="small muted">Also nearby: ${esc(v.companion.venue||v.companion.title)} (permanent attraction)</p>`:''}<details class="date-expand" data-idea="${i}"><summary>View date details</summary>${v.home?homeDateDetail(v,weather.state):''}<div id="screen-${i}" class="hc-recipe-card" aria-live="polite"></div>${!v.home?`<div id="dining-${i}" class="hc-recipe-card" aria-live="polite"></div>`:''}${dateStepDetails(v)}<p class="small muted">${esc(v.note)}</p><p><a target="_blank" rel="noopener" href="${v.event?esc(v.url):'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(v.address)}">${v.event?'Open live event listing':'Open venue on Google Maps'} ↗</a></p>${v.companion?`<p><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(v.companion.address||v.companion.venue||v.companion.title)}">Map: nearby attraction ↗</a></p>`:''}</details><nav><button class="secondary" onclick="likeItin(${i})">${profile.gender==='female'?'♡ Heart':'👍 Like'}</button><button onclick="saveItin(${i})">Save</button><button class="secondary" onclick="copyItin(${i})">Copy</button><button class="secondary" onclick="shareItin(${i})">Share</button></nav>`;anchor.after(el);anchor=el;el.querySelector('.date-expand')?.addEventListener('toggle',e=>{if(!e.target.open||e.target.dataset.loaded)return;e.target.dataset.loaded='1';if(v.home||v.category==='Movie')screenRecommendations(v.home?'netflix':'cinema','screen-'+i);if(!v.home)nearbyDining(v.area,o.budget,'dining-'+i)});}for(let el of [...container.querySelectorAll('.card')]){if(el===cards||el.classList.contains('smart-idea')||el.querySelector('#saved'))continue;el.remove()}}

